import * as React from "react";
import { cn } from "@/lib/utils";
import { SampleButton } from "@/components/ui/sample-button";

export function Hero({ eyebrow, title, body, action, secondary, className }: { eyebrow: string; title: string; body: string; action: string; secondary: string; className?: string }) {
  return (
    <section data-slot="hero" className={cn("flex flex-col gap-6 bg-background px-6 py-16 text-foreground", className)}>
      <span className="text-sm font-medium text-muted-foreground">{eyebrow}</span>
      <h1 className="max-w-2xl text-4xl font-semibold tracking-tight">{title}</h1>
      <p className="max-w-xl text-lg text-muted-foreground">{body}</p>
      <div className="flex gap-3">
        <SampleButton>{action}</SampleButton>
        <SampleButton variant="outline">{secondary}</SampleButton>
      </div>
    </section>
  );
}
